{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "Hardcoded administrator password in Terraform state",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "CRITICAL",
      "explanation": "The `administrator_login_password` is hardcoded directly in the configuration. This exposes sensitive credentials in the Terraform state file, version control history, and plan outputs."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "Weak or default administrator username",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The `administrator_login` uses a generic placeholder 'changemeadmin'. While not strictly a vulnerability if the password is strong, it indicates poor security hygiene and should be replaced with a specific, non-default identifier or managed via variables/Key Vault."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                = \"changeme-simple-mssql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version             = \"12.0\"\n  administrator_login          = var.administrator_login\n  administrator_login_password = var.administrator_login_password\n}\n\nvariable \"administrator_login\" {\n  description = \"The administrator login for the MSSQL server\"\n  type        = string\n  default     = \"sqladmin\"\n}\n\nvariable \"administrator_login_password\" {\n  description = \"The administrator password for the MSSQL server\"\n  type        = string\n  sensitive   = true\n}",
  "fix_summary": "Removed hardcoded credentials from the resource block and replaced them with variable references. Added variable definitions for `administrator_login` and `administrator_login_password`, marking the password as sensitive to prevent exposure in logs and plans. Users must now supply these values securely (e.g., via environment variables, CLI flags, or Key Vault integration) rather than committing them to source code."
}
